ssize_t receive_message(struct kiocb *iocb, struct socket *sock,
                        struct msghdr *msg, size_t len, int flags) {
    struct sock *sk = sock->sk;
    ssize_t result;
    int is_peek = flags & MSG_PEEK;
    int is_oob = flags & MSG_OOB;

    if (sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (is_oob) {
        result = sock_recv_oob(sk, msg, len, flags);
        if (result > 0)
            return result;
    }

    if (sock->type == SOCK_DGRAM) {
        result = sock_recv_dgram(sk, msg, len, flags);
        if (result > 0) {
            if (!(flags & MSG_TRUNC))
                memcpy(msg->msg_name, sk->sk_daddr, sizeof(sk->sk_daddr));
            return result;
        }
    }

    result = sock_recv_queue(sk, msg, len, flags);

    if (result > 0) {
        if (is_peek)
            return result;
        sock_clean_queue(sk, result);
    }

    return result;
}

int receive_socket_message(struct kiocb *iocb, struct socket *sock,
                           struct msghdr *msg, size_t len, int flags) {
    int ret;

    if (sock->sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (flags & MSG_OOB) {
        ret = sock->ops->recv_oob(iocb, sock, msg, len, flags);
        if (ret >= 0)
            return ret;
        if (ret != -ENOSYS)
            return ret;
    }

    ret = sock->ops->recvmsg(iocb, sock, msg, len, flags);
    if (ret >= 0)
        return ret;

    return ret;
}

#include <linux/socket.h>
#include <linux/uio.h>
#include <linux/sockios.h>

int receive_socket_message(struct kiocb *iocb, struct socket *sock,
                           struct msghdr *msg, size_t len, int flags) {
    int ret = 0;
    struct sock *sk = sock->sk;

    if (sk->sk_shutdown & RCV_SHUTDOWN)
        return -ENOTCONN;

    if (flags & MSG_OOB) {
        ret = sock_recv_oob(sk, msg, len, flags);
        if (ret < 0)
            return ret;
        return ret;
    }

    ret = sock_recv_datagram(sk, flags, &msg->msg_name, &msg->msg_namelen,
                             &msg->msg_control, &msg->msg_controllen, len, &msg->msg_flags);

    if (ret > 0) {
        if (msg->msg_name) {
            msg->msg_namelen = ret;
        }
        ret = sock_queue_rcv(sk, msg, ret, flags);
        if (ret < 0)
            return ret;
    }

    return ret;
}

ssize_t receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t len, int flags) {
    ssize_t result;
    struct sk_buff *skb;
    int copied = 0;

    if (sock->state == SS_DISCONNECTED) {
        return -ENOTCONN;
    }

    if (flags & MSG_OOB) {
        // Handle out-of-band data if supported
        skb = sock->sk->sk_urg_data;
        if (skb) {
            copied = skb->len;
            if (copied > len)
                copied = len;
            if (skb_copy_datagram(skb, 0, msg->msg_iov, copied, flags))
                return -EFAULT;
            sock->sk->sk_urg_data = NULL;
            kfree_skb(skb);
            return copied;
        }
    }

    skb = sock->sk->sk_receive_queue;
    if (!skb) {
        return -EAGAIN;
    }

    copied = skb->len;
    if (copied > len)
        copied = len;

    if (skb_copy_datagram(skb, 0, msg->msg_iov, copied, flags))
        return -EFAULT;

    sock->sk->sk_receive_queue = skb->next;
    kfree_skb(skb);

    if (msg->msg_name && sock->sk->sk_peer_name) {
        memcpy(msg->msg_name, &sock->sk->sk_peer_name, sizeof(struct sockaddr));
        msg->msg_namelen = sizeof(struct sockaddr);
    }

    return copied;
}

int receive_socket_message(struct kiocb *iocb, struct socket *sock,
                           struct msghdr *msg, size_t len, int flags) {
    int ret;
    struct sock *sk = sock->sk;

    if (!sk || sk->sk_state == TCP_CLOSE)
        return -ENOTCONN;

    if (sock->type == SOCK_DGRAM) {
        ret = sock_recv_dgram(iocb, sk, msg, len, flags);
        if (ret < 0)
            return ret;

        if (msg->msg_name && sk->sk_family) {
            struct sockaddr *addr;
            int addrlen = sk->sk_family == AF_UNIX ? sizeof(struct sockaddr_un)
                                                    : sizeof(struct sockaddr_in);
            addr = (struct sockaddr *)msg->msg_name;
            if (addr)
                memcpy(addr, &sk->sk_rcv_addr, addrlen);
        }

        return ret;
    } else if (sock->type == SOCK_STREAM || sock->type == SOCK_SEQPACKET) {
        if (flags & MSG_OOB) {
            ret = sock_peek_oob(sk);
            if (ret < 0)
                return ret;

            if (copy_to_iter(msg->msg_iov, len, (void *)sk->sk_oob_data)) {
                sk->sk_oob_data = NULL;
                return ret;
            }
            return -EFAULT;
        }

        ret = sock_recvmsg(iocb, sk, msg, len, flags);
        if (ret < 0)
            return ret;

        if (ret > 0)
            sock_clean_queue(sk, ret);

        return ret;
    }

    return -EINVAL;
}
